            briefText += `MOOD PROFILE: ${mood}\n`;
            briefText += `LIGHTING MAP: ${lighting}\n`;
            briefText += `ASPECT RATIO: ${ratio}\n`;
            briefText += `PRODUCTION LIMITS: ${customConstraint}\n\n`;
