                    briefText += `  Setup:  ${angleEl.innerText.trim()}\n`;
                    briefText += `  Action: ${actionEl.innerText.trim()}\n\n`;
                }
            }

            document.getElementById('brief-block').innerText = briefText;
        }

        function copyBrief() {
