                { id: "01", name: "01. Hook / Scale", setup: "Extreme Close-Up (Macro)", action: "Establishing macro texture, framing, or critical branding feature." },
                { id: "02", name: "02. Context / Identity", setup: "", action: "Interactions with nearby assets under selected environment values." },
                { id: "03", name: "03. Kinetic Flow", setup: "Dynamic Framing", action: "Capturing mechanical function or environmental fluid responses." },
                { id: "04", name: "04. Hero Outro", setup: "Low Angle (Hero Shot)", action: "Locking focal length cleanly across complete silhouette package layout." }
            ],
            Person: [
                { id: "01", name: "01. Int. Character", setup: "Close-Up Profile", action: "Capturing primary expressions or local posture setups." },
                { id: "02", name: "02. Physical Kinesthetics", setup: "", action: "Tracking bodily motion elements safely through immediate sets." },
                { id: "03", name: "03. Deep Environmental", setup: "Wide Tracking View", action: "Isolating subject scales directly against structural backgrounds." },
                { id: "04", name: "04. Clean Resolution", setup: "Eye-Level Portrait", action: "Subject locks gaze alignment directly with focal axis line." }
            ],
            Place: [
                { id: "01", name: "01. Spatial Anchor", setup: "Bird's Eye Top-Down", action: "Establishing total layout boundaries and geometric footprints." },
                { id: "02", name: "02. Architectural Texture", setup: "", action: "Isolating surface material parameters across geometric lines." },
                { id: "03", name: "03. Internal Sweep", setup: "Wide Angle Jib", action: "Drawing structural dimension directly into interior frame planes." },
                { id: "04", name: "04. Abstract Vignette", setup: "Geometric Silhouette", action: "Reducing complex patterns down to high-contrast spatial graphics." }
            ]
        };

        function selectSubjectType(type) {
            operationalSubjectType = type;
            const buttons = document.querySelectorAll('.subject-btn');
            buttons.forEach(btn => {
                btn.classList.remove('active');
            });
            document.getElementById(`type-${type}`).classList.add('active');
        }

        function clearCardContainer() {
            const container = document.getElementById('cards-insertion-point');
            while (container.firstChild) {
                container.removeChild(container.firstChild);
            }
        }

        function clearChecklistContainer() {
            const container = document.getElementById('checklist-insertion-point');
            while (container.firstChild) {
                container.removeChild(container.firstChild);
            }
        }

        function createShotCardNode(shotData, index, displayRatio, defaultAngle, alternateLighting, baseMotion) {
            const cardEl = document.createElement('div');
            cardEl.className = 'shot-card';

            // Top Header Banner Node
            const headerRow = document.createElement('div');
            headerRow.className = 'card-meta-line';

            const titleSpan = document.createElement('span');
            titleSpan.className = 'card-title';
            titleSpan.textContent = shotData.name;

            const badgeSpan = document.createElement('span');
            badgeSpan.className = 'card-badge';
            badgeSpan.textContent = displayRatio.split(' ')[0];

            headerRow.appendChild(titleSpan);
            headerRow.appendChild(badgeSpan);
            cardEl.appendChild(headerRow);

            // Framing Parameter Field Input Node
            const setupBlock = document.createElement('div');
            setupBlock.className = 'card-field-block';

            const setupLabel = document.createElement('div');
            setupLabel.className = 'field-label';
            setupLabel.textContent = 'Framing / Setup';

            const setupEditable = document.createElement('div');
            setupEditable.className = 'editable-area';
            setupEditable.contentEditable = 'true';
            setupEditable.id = `editable-setup-${index}`;
            setupEditable.textContent = shotData.setup || defaultAngle;

            setupBlock.appendChild(setupLabel);
            setupBlock.appendChild(setupEditable);
            cardEl.appendChild(setupBlock);

            // Narrative Action Field Input Node
            const actionBlock = document.createElement('div');
            actionBlock.className = 'card-field-block';

            const actionLabel = document.createElement('div');
            actionLabel.className = 'field-label';
            actionLabel.textContent = 'Action / Manifestation';

            const actionEditable = document.createElement('div');
            actionEditable.className = 'editable-area';
            actionEditable.contentEditable = 'true';
            actionEditable.id = `editable-action-${index}`;

            // Clean injection construction if standard fallback context strings are required
            if (!shotData.setup) {
                actionEditable.textContent = `Tracking subject transformations under ${alternateLighting.toLowerCase()} rules. ${baseMotion}.`;
            } else {
                actionEditable.textContent = shotData.action;
            }

            actionBlock.appendChild(actionLabel);
            actionBlock.appendChild(actionEditable);
            cardEl.appendChild(actionBlock);

            // Event Listeners for Automatic Text Synthesis Realignment
            setupEditable.addEventListener('input', updateStructuredBriefOutput);
            actionEditable.addEventListener('input', updateStructuredBriefOutput);

            return cardEl;
        }

        function appendChecklistItem(textString) {
            const container = document.getElementById('checklist-insertion-point');

            const labelNode = document.createElement('label');
            labelNode.className = 'check-item';

            const inputNode = document.createElement('input');
            inputNode.type = 'checkbox';

            const labelText = document.createElement('span');
            labelText.textContent = textString;

            labelNode.appendChild(inputNode);
            labelNode.appendChild(labelText);
            container.appendChild(labelNode);
        }

        function buildStoryboard() {
            const subjectKind = operationalSubjectType || 'Product';
            const textDescriptor = document.getElementById('input-detail').value.trim() || `Unspecified ${subjectKind}`;
            const selectedMood = document.getElementById('select-mood').value;
            const selectedLighting = document.getElementById('select-lighting').value;
            const chosenAngle = document.getElementById('select-angle').value;
            const chosenMotion = document.getElementById('select-motion').value;
            const activeRatio = document.getElementById('select-ratio').value;
            const constraintsText = document.getElementById('input-constraint').value.trim() || 'None';

            clearCardContainer();
            clearChecklistContainer();

            // Construct 4 Card Component Nodes sequentially using safe DOM APIs
            const sequenceBlueprint = sequentialArchetypes[subjectKind];
            const cardsTarget = document.getElementById('cards-insertion-point');

            sequenceBlueprint.forEach((shotUnit, idx) => {
                const builtCard = createShotCardNode(shotUnit, idx, activeRatio, chosenAngle, selectedLighting, chosenMotion);
                cardsTarget.appendChild(builtCard);
            });

            // Construct System Safety Checklist Groups safely
            const titleLabel = document.createElement('div');
            titleLabel.className = 'label-style';
            titleLabel.style.marginBottom = '6px';
            titleLabel.textContent = 'Production Checklist';
            document.getElementById('checklist-insertion-point').appendChild(titleLabel);

            appendChecklistItem(`Verify framing boundary safely matches ${activeRatio.split(' ')[0]} lines.`);
            appendChecklistItem(`Confirm spatial environment supports ${selectedLighting.toLowerCase()} parameters.`);
            appendChecklistItem(`Verify hardware rigs allow clean execution of: ${chosenMotion.toLowerCase()}.`);
            appendChecklistItem(`Enforce target constraint parameter: ${constraintsText}.`);

            // Expose structural component panel grouping to screen interface layout
            document.getElementById('output-workspace').classList.remove('hidden');
            updateStructuredBriefOutput();

            // Smooth scroll interface adjustment for mobile viewing parameters
            document.getElementById('output-workspace').scrollIntoView({ behavior: 'smooth' });
        }

        function updateStructuredBriefOutput() {
            const typeValue = operationalSubjectType || 'Product';
            const detailValue = document.getElementById('input-detail').value.trim() || `Unspecified ${typeValue}`;
            const moodValue = document.getElementById('select-mood').value;
            const lightingValue = document.getElementById('select-lighting').value;
            const ratioValue = document.getElementById('select-ratio').value;
            const constraintValue = document.getElementById('input-constraint').value.trim() || 'None';

            let trackingDocument = `=== PRODUCTION SHOT BRIEF ===\n`;
            trackingDocument += `SUBJECT: ${detailValue} (${typeValue})\n`;
            trackingDocument += `MOOD PROFILE: ${moodValue}\n`;
            trackingDocument += `LIGHTING MAP: ${lightingValue}\n`;
            trackingDocument += `ASPECT RATIO: ${ratioValue}\n`;
            trackingDocument += `PRODUCTION LIMITS: ${constraintValue}\n\n`;
            trackingDocument += `--- RUN OF SHOTS ---\n`;

            for (let i = 0; i < 4; i++) {
                const targetSetupNode = document.getElementById(`editable-setup-${i}`);
                const targetActionNode = document.getElementById(`editable-action-${i}`);

                if (targetSetupNode && targetActionNode) {
                    trackingDocument += `SHOT 0${i + 1}:\n`;
                    trackingDocument += `  Setup:  ${targetSetupNode.textContent.trim()}\n`;
                    trackingDocument += `  Action: ${targetActionNode.textContent.trim()}\n\n`;
                }
            }

            document.getElementById('raw-brief-block').textContent = trackingDocument;
        }

        function copyBriefText() {
            const textSource = document.getElementById('raw-brief-block').textContent;
            navigator.clipboard.writeText(textSource).then(() => {
                alert('Brief copied to clipboard.');
            }).catch(() => {
                alert('Unable to write text automatically to copy track.');
            });
        }

        function exportBriefFile() {
            const textSource = document.getElementById('raw-brief-block').textContent;
            if (!textSource) {
                alert('No compiled content available to export.');
                return;
            }

            const typeValue = operationalSubjectType || 'Product';
            const detailValue = document.getElementById('input-detail').value.trim() || `Unspecified_${typeValue}`;
            // Sanitize string to create a safe file name layout
            const safeName = detailValue.replace(/[^a-z0-9]/gi, '_').toLowerCase();
            const fileName = `shot_brief_${safeName}.txt`;

            const blob = new Blob([textSource], { type: 'text/plain;charset=utf-8;' });
            const link = document.createElement('a');

            if (navigator.msSaveBlob) { // IE 10+ Fallback
                navigator.msSaveBlob(blob, fileName);
            } else {
                const url = URL.createObjectURL(blob);
                link.setAttribute('href', url);
                link.setAttribute('download', fileName);
                link.style.visibility = 'hidden';
                document.body.appendChild(link);
                link.click();
                document.body.removeChild(link);
                URL.revokeObjectURL(url);
            }
        }

        function resetWorkspace() {
            document.getElementById('input-detail').value = '';
            document.getElementById('input-constraint').value = '';
            document.getElementById('select-mood').selectedIndex = 0;
            document.getElementById('select-lighting').selectedIndex = 0;
            document.getElementById('select-angle').selectedIndex = 0;
            document.getElementById('select-motion').selectedIndex = 0;
            document.getElementById('select-ratio').selectedIndex = 0;

            clearCardContainer();
            clearChecklistContainer();
            document.getElementById('raw-brief-block').textContent = '';
            document.getElementById('output-workspace').classList.add('hidden');

            selectSubjectType('Product');
            window.scrollTo({ top: 0, behavior: 'smooth' });
        }

        // Run default profile registration on execution mount
        selectSubjectType('Product');
    </script>
